import{_ as o,c as t,o as i,a2 as l}from"./chunks/framework.CFHYvIe4.js";const c=JSON.parse('{"title":"Building the S1API Project","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/building.md","filePath":"contributing/building.md","lastUpdated":1756461828000}'),a={name:"contributing/building.md"};function n(r,e,s,d,p,h){return i(),t("div",null,e[0]||(e[0]=[l(`<h1 id="building-the-s1api-project" tabindex="-1">Building the S1API Project <a class="header-anchor" href="#building-the-s1api-project" aria-label="Permalink to &quot;Building the S1API Project&quot;">​</a></h1><p>This guide explains how to set up your development environment and build the S1API project.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before you begin, make sure you have the following installed:</p><ul><li><a href="https://visualstudio.microsoft.com/" target="_blank" rel="noreferrer">Visual Studio 2019 or later</a> with the following workloads: <ul><li>.NET desktop development</li><li>Game development with Unity</li></ul></li><li><a href="https://dotnet.microsoft.com/download/dotnet" target="_blank" rel="noreferrer">.NET Standard 2.1 SDK</a></li><li><a href="https://dotnet.microsoft.com/download/dotnet" target="_blank" rel="noreferrer">.NET 6.0 SDK</a></li><li><a href="https://git-scm.com/downloads" target="_blank" rel="noreferrer">Git</a> for version control</li><li><a href="https://github.com/LavaGang/MelonLoader" target="_blank" rel="noreferrer">MelonLoader</a> installed for your Schedule One game installation</li></ul><h2 id="setting-up-the-development-environment" tabindex="-1">Setting Up the Development Environment <a class="header-anchor" href="#setting-up-the-development-environment" aria-label="Permalink to &quot;Setting Up the Development Environment&quot;">​</a></h2><ol><li><p><strong>Clone the Repository</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/KaBooMa/S1API.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> S1API</span></span></code></pre></div></li><li><p><strong>Configure Build Properties</strong></p><p>The project uses build property files to specify paths to dependencies. Example files are included in the repository:</p><ul><li><code>github.build.props</code> - Used for GitHub CI/CD builds</li><li><code>example.build.props</code> - A template with examples of proper paths</li></ul><p>For local development, create a <code>local.build.props</code> file in the root directory by copying one of the example files and adjusting the paths to match your system. The file should contain paths to your game assemblies and MelonLoader installation.</p><p>Key properties to configure include:</p><ul><li><code>AutomateLocalDeployment</code> - Set to <code>true</code> to automatically deploy builds to your game installation</li><li><code>MelonLoaderAssembliesPath</code> - Path to MelonLoader assemblies</li><li><code>BepInExAssembliesPath</code> - Path to BepInEx core files (if using BepInEx)</li><li><code>MonoAssembliesPath</code> - Path to game&#39;s managed assemblies for Mono builds</li><li><code>Il2CppAssembliesPath</code> - Path to game&#39;s Il2Cpp assemblies</li><li><code>LocalMonoDeploymentPath</code> - Path to your Mono version of the game</li><li><code>LocalIl2CppDeploymentPath</code> - Path to your Il2Cpp version of the game</li></ul><p>Refer to the example files in the repository for the complete set of properties and proper formatting.</p></li><li><p><strong>Open the Solution</strong></p><p>Open the <code>S1API.sln</code> file in Visual Studio.</p></li></ol><h2 id="building-the-project" tabindex="-1">Building the Project <a class="header-anchor" href="#building-the-project" aria-label="Permalink to &quot;Building the Project&quot;">​</a></h2><p>S1API needs to be built for both Mono and Il2Cpp environments:</p><h3 id="building-for-mono" tabindex="-1">Building for Mono <a class="header-anchor" href="#building-for-mono" aria-label="Permalink to &quot;Building for Mono&quot;">​</a></h3><ol><li>In Visual Studio, set the solution configuration to <code>Mono</code></li><li>Build the solution (F6 or Ctrl+Shift+B)</li><li>The output will be located in the <code>bin/Mono/netstandard2.1/S1API.dll</code> directory</li></ol><h3 id="building-for-il2cpp" tabindex="-1">Building for Il2Cpp <a class="header-anchor" href="#building-for-il2cpp" aria-label="Permalink to &quot;Building for Il2Cpp&quot;">​</a></h3><ol><li>In Visual Studio, set the solution configuration to <code>Il2Cpp</code></li><li>Build the solution (F6 or Ctrl+Shift+B)</li><li>The output will be located in the <code>bin/Il2Cpp/netstandard2.1/S1API.dll</code> directory</li></ol><h2 id="automated-deployment" tabindex="-1">Automated Deployment <a class="header-anchor" href="#automated-deployment" aria-label="Permalink to &quot;Automated Deployment&quot;">​</a></h2><p>If you&#39;ve configured <code>AutomateLocalDeployment</code> to <code>true</code> in your <code>local.build.props</code>, the build process will automatically copy the compiled DLLs to your game&#39;s plugins folder:</p><ul><li>When building the <code>Mono</code> configuration, both Mono and Il2Cpp versions will be copied to your Mono game installation</li><li>When building the <code>Il2Cpp</code> configuration, both versions will be copied to your Il2Cpp game installation</li></ul><h2 id="running-tests" tabindex="-1">Running Tests <a class="header-anchor" href="#running-tests" aria-label="Permalink to &quot;Running Tests&quot;">​</a></h2><p>If the project includes tests:</p><ol><li>Open the Test Explorer in Visual Studio (Test &gt; Test Explorer)</li><li>Click &quot;Run All Tests&quot; to run the unit tests</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h3><ul><li><strong>Missing References</strong>: Make sure your <code>local.build.props</code> file has the correct paths to game assemblies</li><li><strong>Build Errors</strong>: Check that you have the correct .NET Standard version installed</li><li><strong>Deployment Errors</strong>: Verify your game paths in the <code>local.build.props</code> file</li></ul><h3 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h3><p>If you encounter issues while building the project, feel free to:</p><ol><li>Check the GitHub issues to see if it&#39;s a known problem</li><li>Ask for help in the Schedule 1 Modding Discord server</li><li>Create a new issue with details about your problem</li></ol>`,25)]))}const g=o(a,[["render",n]]);export{c as __pageData,g as default};
